package org.mixxx;

import android.app.Notification;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.app.PendingIntent;
import android.app.Service;
import android.content.Context;
import android.content.Intent;
import android.content.pm.ServiceInfo;
import android.os.Build;
import android.os.IBinder;
import android.os.PowerManager;
import android.util.Log;

/// Keeps Mixxx running while it plays: a foreground service with a
/// notification and a partial wake lock, so that Android doesn't slow down or
/// end the app when the screen turns off, during a call or in another app
/// (above all with Mixxx' own USB audio driver, which Android doesn't see as
/// playing). Started and stopped by the native code (see QmlApplication).
public class PlaybackService extends Service {
    private static final String TAG = "MixxxPlayback";
    private static final String CHANNEL_ID = "playback";
    private static final int NOTIFICATION_ID = 7422;

    private PowerManager.WakeLock mWakeLock;

    public static void start(Context context, String title, String text) {
        Intent intent = new Intent(context, PlaybackService.class);
        intent.putExtra(Intent.EXTRA_TITLE, title);
        intent.putExtra(Intent.EXTRA_TEXT, text);
        try {
            context.startForegroundService(intent);
        } catch (RuntimeException e) {
            // E.g. ForegroundServiceStartNotAllowedException while in the
            // background: tried again on the next check
            Log.w(TAG, "Unable to start the playback service", e);
        }
    }

    public static void stop(Context context) {
        context.stopService(new Intent(context, PlaybackService.class));
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        NotificationManager manager = getSystemService(NotificationManager.class);
        if (manager.getNotificationChannel(CHANNEL_ID) == null) {
            NotificationChannel channel = new NotificationChannel(
                    CHANNEL_ID, "Mixxx", NotificationManager.IMPORTANCE_LOW);
            channel.setShowBadge(false);
            manager.createNotificationChannel(channel);
        }
        String title = intent != null ? intent.getStringExtra(Intent.EXTRA_TITLE) : null;
        String text = intent != null ? intent.getStringExtra(Intent.EXTRA_TEXT) : null;
        Notification.Builder builder = new Notification.Builder(this, CHANNEL_ID)
                .setContentTitle(title != null ? title : "Mixxx")
                .setContentText(text != null ? text : "")
                .setSmallIcon(getApplicationInfo().icon)
                .setOngoing(true)
                .setOnlyAlertOnce(true)
                .setCategory(Notification.CATEGORY_TRANSPORT);
        Intent openApp = getPackageManager().getLaunchIntentForPackage(getPackageName());
        if (openApp != null) {
            builder.setContentIntent(PendingIntent.getActivity(this, 0, openApp,
                    PendingIntent.FLAG_IMMUTABLE | PendingIntent.FLAG_UPDATE_CURRENT));
        }
        try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                startForeground(NOTIFICATION_ID, builder.build(),
                        ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);
            } else {
                startForeground(NOTIFICATION_ID, builder.build());
            }
        } catch (RuntimeException e) {
            Log.w(TAG, "Unable to run the playback service in the foreground", e);
            stopSelf();
            return START_NOT_STICKY;
        }
        if (mWakeLock == null) {
            PowerManager power = getSystemService(PowerManager.class);
            mWakeLock = power.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "mixxx:playback");
            mWakeLock.setReferenceCounted(false);
            mWakeLock.acquire();
        }
        Log.i(TAG, "Playing: kept running in the foreground");
        return START_NOT_STICKY;
    }

    @Override
    public void onDestroy() {
        if (mWakeLock != null && mWakeLock.isHeld()) {
            mWakeLock.release();
        }
        mWakeLock = null;
        Log.i(TAG, "Not playing any more: the foreground service ends");
        super.onDestroy();
    }

    @Override
    public IBinder onBind(Intent intent) {
        return null;
    }

    @Override
    public void onTaskRemoved(Intent rootIntent) {
        // Swiped away from the recent apps: Mixxx ends, and so does this
        stopSelf();
        super.onTaskRemoved(rootIntent);
    }
}
